/* Palabras del desafío final, por nivel (para editar el contenido, usar este mapa) */
DF.palabras = DF.levels.map(l => ({ n:l.n, words:l.palabras, clue:l.pista }));

/* Denuncia / testimonios / pruebas de cada nivel (las 3 carpetas del caso) */
DF.carpetas = DF.levels.map(l => ({ n:l.n, denuncia:l.caso.denuncia, testimonios:l.caso.testimonios, pruebas:l.caso.pruebas, devolucion:l.caso.devolucion }));
